class CheckoutUnavailable(Exception):
    pass


def charge_order(order, gateway, max_attempts=2):
    if not isinstance(order['id'], str) or not order['id']:
        raise ValueError('Order identity is required')
    amount = order['amount_cents']
    if type(amount) is not int or amount <= 0:
        raise ValueError('Charge must be positive integer cents')
    if type(max_attempts) is not int or not 1 <= max_attempts <= 3:
        raise ValueError('Invalid attempt count')
    for attempt in range(max_attempts):
        key = 'order:' + order['id']
        try:
            receipt = gateway.charge(amount, idempotency_key=key)
        except TimeoutError:
            if attempt + 1 == max_attempts:
                raise CheckoutUnavailable('Payment status unavailable')
            continue
        return {'order_id': order['id'], 'receipt': receipt}
    raise CheckoutUnavailable('No payment attempt completed')

